function Avatar({name,size='normal',bot=false}:{name:string,size?:string,bot?:boolean}){return <span className={`avatar ${size} ${bot?'bot-avatar':''}`}>{bot?<Bot size={20}/>:initials(name)}</span>;}
function Pill({children,tone='purple'}:{children:React.ReactNode,tone?:string}){return <span className={`pill ${tone}`}>{children}</span>;}
function Switch({checked,onChange,label}:{checked:boolean,onChange:()=>void,label:string}){return <button type="button" className={`switch ${checked?'on':''}`} role="switch" aria-checked={checked} aria-label={label} onClick={onChange}><span/></button>;}
