function Empty({icon:Icon=MessageCircle,title,text,action}:{icon?:any,title:string,text:string,action?:React.ReactNode}){return <div className="empty-state"><span className="empty-icon"><Icon size={28}/></span><h3>{title}</h3><p>{text}</p>{action}</div>;}
