 {page==='agenda'&&!personalMode&&<div className="agenda-grid"><section className="card"><div className="section-head"><div><h3>Próximas conversas</h3><p>Reuniões com contexto, sem esquecer os detalhes</p></div><CalendarDays size={19}/></div>{data.meetings.filter(m=>m.status==='agendada').length?data.meetings.filter(m=>m.status==='agendada').sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)).map(m=><article className="meeting-item" key={m.id}><div className="meeting-date"><b>{new Date(m.at).getDate()}</b><span>{new Date(m.at).toLocaleDateString('pt-BR',{month:'short'})}</span></div><div><Pill tone="neutral"><Clock size={11}/>{time(m.at)}</Pill><h3>{m.title}</h3><p>{m.contactName} {m.seller&&`· com ${m.seller}`}</p>{m.notes&&<p className="meeting-notes">{m.notes}</p>}<div className="meeting-actions"><button className="text-btn" onClick={()=>{const c=data.contacts.find(c=>c.id===m.contactId);if(c){openContact(c);setProfile(true);}}}>Ver contexto <ArrowUpRight size={13}/></button><button className="text-btn" onClick={()=>act(`meetings/${m.id}`,'PATCH',{status:'concluida'},'Reunião concluída.')}>Concluir <Check size={13}/></button><button className="text-btn muted" onClick={()=>setModal({type:'cancelMeeting',item:m})}>Cancelar</button></div></div></article>):<Empty icon={CalendarDays} title="Sua agenda está aberta" text="Adicione horários disponíveis para que seus agentes possam agendar uma conversa."/>}</section><section className="card slots-card"><div className="section-head"><div><h3>Horários disponíveis</h3><p>Os agentes só oferecem estes horários</p></div><button className="icon-btn" aria-label="Adicionar horário" onClick={()=>setModal({type:'slot'})}><Plus size={20}/></button></div>{slots.filter(s=>Date.parse(s.at)>Date.now()).length?slots.filter(s=>Date.parse(s.at)>Date.now()).map(s=><div className="slot" key={s.id}><CalendarDays size={17}/><span><strong>{date(s.at)}</strong><small>{s.seller||'Time comercial'}</small></span><button className="icon-btn" aria-label="Excluir horário" onClick={async()=>{if(await act(`slots/${s.id}`,'DELETE'))setSlots(v=>v.filter(r=>r.id!==s.id));}}><X size={15}/></button></div>):<div className="mini-empty"><Clock size={27}/><p>Escolha os horários em que seu time pode conversar.</p></div>}<button className="btn dashed" onClick={()=>setModal({type:'slot'})}><Plus size={15}/> Adicionar horário</button><p className="slots-foot">Fuso: {data.company.settings.timezone||'America/Sao_Paulo'}. Reuniões ficam na agenda do STARSIS.</p></section></div>}
 {page==='conexoes'&&<><div className="connections-intro"><span className="whatsapp-symbol"><MessageCircle size={29}/></span><div><h2>Seu WhatsApp encontra<br/>um novo jeito de trabalhar.</h2><p>Adicione um número e leia o QR Code pelo WhatsApp.<br/>As novas conversas chegam aqui automaticamente.</p></div><div className="connection-steps"><span><b>01</b> Adicione o número</span><span><b>02</b> Escaneie o QR Code</span><span><b>03</b> Deixe a conversa fluir</span></div></div><div className="number-grid">{data.numbers.map(n=><section className="card number-card" key={n.id}><div className="number-top"><span className="number-icon"><Smartphone size={25}/></span><Pill tone={n.status==='connected'?'green':'neutral'}><i/>{n.status==='connected'?'Conectado':n.status==='qr_pending'?'Aguardando QR':n.status==='connecting'?'Conectando':'Desconectado'}</Pill></div><h3>{n.name}</h3><p>{n.phone?`+${n.phone}`:'Pronto para conectar um número'}</p><div className="number-divider"/><div className="number-features"><span><CheckCircle2 size={14}/> Sessão exclusiva do STARSIS</span><span><CheckCircle2 size={14}/> Histórico por contato</span><span><CheckCircle2 size={14}/> Mensagens e notas de voz</span></div>{n.status==='connected'?<button className="btn secondary full" onClick={()=>setModal({type:'disconnect',item:n})}><Link2 size={15}/> Gerenciar conexão</button>:<button className="btn primary full" disabled={busy} onClick={async()=>{if(demo){notify('QR Code disponível na sua empresa, fora da demonstração.');return;}if(await act(`numbers/${n.id}/connect`,'POST',{},'Preparando o QR Code…'))setQr(n);}}><Smartphone size={16}/> Conectar WhatsApp <ArrowUpRight size={16}/></button>}{n.status==='connected'&&<><button className="btn secondary full group-button" disabled={busy} onClick={()=>syncGroups(n.id)}><Users size={16}/> Sincronizar grupos</button><button className="text-btn group-button" onClick={()=>setModal({type:'joinGroup',numberId:n.id})}>Entrar em grupo por convite</button></>}</section>)}<button className="new-number-card" onClick={()=>setModal({type:'number'})}><span><Plus size={27}/></span><h3>{data.numbers.length?'Mais um WhatsApp?':'Conecte seu primeiro número'}</h3><p>Organize seus números comerciais<br/>em um mesmo espaço.</p></button></div><div className="help-note"><ShieldCheck size={18}/><p>No celular: WhatsApp → Configurações ou menu → Aparelhos conectados → Conectar aparelho. No primeiro acesso, a sincronização pode levar alguns minutos.</p></div></>}
