 {modal.type==='contact'&&<><Field label="Nome do contato" name="name" required placeholder="Como a pessoa se chama?"/><Field label="WhatsApp com DDI e DDD" name="phone" required placeholder="Ex.: 5511999999999"/><Field label="Conectar ao número"><select name="numberId" required><option value="">Selecione um WhatsApp</option>{data.numbers.map(n=><option key={n.id} value={n.id}>{n.name}</option>)}</select></Field></>}
 {modal.type==='number'&&<><Field label="Nome para identificar o WhatsApp" name="name" placeholder="Ex.: Comercial, Loja Centro…" required/><p className="form-help">Depois de adicionar, clique em Conectar para ler o QR Code. Nenhuma sessão de outro sistema será usada.</p></>}
 {modal.type==='automation'&&<><Field label="Nome da automação" name="name" value={modal.item?.name} placeholder="Ex.: Retomar uma proposta" required/><div className="form-grid"><Field label="Quando o contato estiver em"><select name="stage" defaultValue={modal.item?.stage||'proposta'}>{stages.filter(([s])=>!['ganho','perdido'].includes(s)).map(([s,n])=><option key={s} value={s}>{n}</option>)}</select></Field><Field label="Esperar quantas horas?" name="delayHours" type="number" value={modal.item?.delayHours||24} required/></div><Field label="Mensagem de follow-up" name="text" value={modal.item?.text} placeholder="Oi, {nome}! Ficou alguma dúvida?" required textarea/><p className="form-help">Use {'{nome}'} para personalizar. Enviamos após a última resposta da empresa, uma vez por ciclo. Conversas assumidas por humanos ou com pedido de parada ficam de fora.</p><label className="check-field"><input type="checkbox" name="enabled" defaultChecked={modal.item?.enabled||false}/> Ativar esta automação</label></>}
 {modal.type==='meeting'&&<><Field label="Contato"><select name="contactId" defaultValue={modal.contactId||''} required><option value="">Selecione o contato</option>{data.contacts.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Assunto" name="title" placeholder="Ex.: Conhecer o projeto" required/><Field label="Data e hora" name="at" type="datetime-local" required/><Field label="Vendedor responsável" name="seller" placeholder="Quem vai participar?"/><p className="form-help">O horário digitado usa o fuso do seu aparelho. A reunião será registrada na agenda do STARSIS.</p></>}
