 {modal.type==='agent'&&<form className="modal-form agent-form" noValidate onSubmit={saveModal}><div className="modal-tabs">{[['perfil','01','Identidade'],['regras','02','Como atende'],['voz','03','Inteligência e voz']].map(([s,n,t])=><button type="button" key={s} className={agentTab===s?'active':''} onClick={()=>setAgentTab(s)}><small>{n}</small>{t}</button>)}</div><div className={agentTab==='perfil'?'':'hidden'}><div className="template-picks">{[['SDR · Qualificação','Sofia'],['Vendas · Negociação','Lucas'],['Follow-up · Relacionamento','Lia']].map(([role,n])=><button type="button" key={role} onClick={e=>{const form=e.currentTarget.form!;(form.elements.namedItem('role')as HTMLInputElement).value=role;(form.elements.namedItem('name')as HTMLInputElement).value=n;setSelectedStages(role.startsWith('SDR')?['novo','qualificacao']:role.startsWith('Vendas')?['proposta']:['todos']);}}><Sparkles size={13}/>{role.split(' · ')[0]}</button>)}</div><div className="form-grid"><Field label="Nome do agente" name="name" value={modal.agent?.name} placeholder="Ex.: Sofia" required/><Field label="Papel no time" name="role" value={modal.agent?.role||(personalMode?'Assistente pessoal':'')} placeholder="Ex.: SDR · Qualificação" required/></div>{personalMode&&<><Field label="Como o bot deve conversar?"><select name="identityMode" defaultValue={modal.agent?.identityMode||'assistant'}><option value="assistant">Como meu assistente</option><option value="self">No meu tom, em meu nome</option></select></Field><div className="form-grid"><Field label="Esperar antes de responder"><select name="delaySeconds" defaultValue={modal.agent?.delaySeconds||120}><option value="60">1 minuto</option><option value="120">2 minutos</option><option value="300">5 minutos</option></select></Field><Field label="Quando pedir minha aprovação?"><select name="approvalMode" defaultValue={modal.agent?.approvalMode||'uncertain'}><option value="uncertain">Quando faltar informação ou houver decisão</option><option value="always">Antes de toda resposta</option></select></Field></div><p className="form-help">Se você responder antes do prazo, o bot cancela a resposta. Respostas que dependam de você aparecem em Meu assistente → Aprovações.</p></>}<Field label="Personalidade" name="personality" value={modal.agent?.personality||'Acolhedor, objetivo e consultivo. Faz uma pergunta por vez.'} textarea/><div className="field"><span>Em quais etapas ele atende?</span><div className="stage-picks">{[['todos','Toda a negociação'],...stages.filter(([s])=>!['ganho','perdido'].includes(s))].map(([s,n])=><button type="button" className={selectedStages.includes(s)?'selected':''} key={s} onClick={()=>setSelectedStages(v=>s==='todos'?['todos']:v.includes(s)?v.filter(x=>x!==s):[...v.filter(x=>x!=='todos'),s])}>{selectedStages.includes(s)&&<Check size={13}/>} {n}</button>)}</div></div></div><div className={agentTab==='regras'?'':'hidden'}><Field label="O que ele precisa saber?" name="knowledge" value={modal.agent?.knowledge} textarea placeholder="Produtos, serviços, preços, perguntas frequentes e informações aprovadas da empresa."/><Field label="Regras do atendimento" name="rules" value={modal.agent?.rules||'Entenda a necessidade do cliente. Não invente preços nem descontos. Se precisar de uma pessoa, sinalize. Não insista quando o cliente pedir para parar.'} textarea/><label className="check-field"><input type="checkbox" name="notes" defaultChecked={modal.agent?.notes!==false}/> Registrar informações importantes no caderno do contato</label><label className="check-field"><input type="checkbox" name="schedule" defaultChecked={modal.agent?.schedule||false}/> Agendar reuniões nos horários disponíveis</label><Field label="Vendedor para receber as reuniões" name="handoff" value={modal.agent?.handoff} placeholder="Nome do responsável comercial"/></div><div className={agentTab==='voz'?'':'hidden'}><div className="form-grid"><Field label="Provedor de inteligência"><select name="provider" defaultValue={modal.agent?.provider||'gemini'}><option value="gemini">Google Gemini · texto e compreensão de áudio</option><option value="anthropic">Anthropic Claude · texto</option><option value="openai">OpenAI · texto</option></select></Field><Field label="Modelo" name="model" value={modal.agent?.model||'gemini-2.5-flash'} placeholder="Identificador do modelo no provedor" required/></div><Field label={modal.agent?.hasKey?'Chave de IA · já configurada':'Chave de API do provedor'} name="apiKey" type="password" placeholder={modal.agent?.hasKey?'Deixe em branco para manter a chave':'Cole a chave da sua conta do provedor'}/><p className="form-help">A chave é guardada com proteção e não volta para o navegador. Confira o modelo no seu provedor antes de ativar.</p><Field label="Como ele responde?"><select name="voiceMode" defaultValue={modal.agent?.voiceMode||'mirror'}><option value="mirror">Acompanhar o cliente · áudio recebe áudio</option><option value="text">Sempre por texto</option><option value="audio">Preferir mensagem de voz</option></select></Field><Field label="Voz personalizada (opcional)" name="voice" value={modal.agent?.voice} placeholder="ID da voz ElevenLabs · em branco usa a padrão"/><p className="form-help">Voz usa ElevenLabs quando disponível; Gemini oferece uma alternativa. Quando a voz falha, o cliente recebe o texto e você vê um aviso no painel.</p></div><div className="agent-enable"><div><strong>Ativar este agente</strong><p>O atendimento automático da empresa também precisa estar ligado.</p></div><input type="checkbox" name="enabled" defaultChecked={modal.agent?.enabled||false} aria-label="Ativar agente"/></div><div className="dialog-actions"><button type="button" className="btn secondary" onClick={()=>setAgentTab(agentTab==='perfil'?'regras':agentTab==='regras'?'voz':'perfil')}>{agentTab==='voz'?'Voltar à identidade':'Próximo passo'}<ArrowRight size={15}/></button><button className="btn primary" disabled={busy}>Salvar agente <Check size={16}/></button></div></form>}
 {modal.type==='testAgent'&&<form className="modal-form" onSubmit={async e=>{const f=readForm(e);setBusy(true);try{setTestReply(demo?'Oi! Que bom ter você por aqui 😊 Me conta um pouco sobre a sua empresa e como podemos te ajudar?':(await json(`agents/${modal.agent.id}/test`,'POST',f)).reply);}catch(e:any){notify(e.message);}finally{setBusy(false);}}}><Field label="Mensagem de teste" name="text" value="Olá! Quero conhecer os serviços de vocês." textarea required/>{testReply&&<div className="test-reply"><Bot size={18}/><p>{testReply}</p></div>}<p className="form-help">Este teste não envia mensagens para nenhum WhatsApp.</p><button className="btn primary" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Play size={15}/>} Testar resposta</button></form>}
 {modal.type==='forward'&&<form className="modal-form" onSubmit={async e=>{const f=readForm(e);let body:Row={contactId:f.contactId,text:modal.message.text,requestId:uid()};if(modal.message.mediaId){const blob=await mediaBlob(modal.message.mediaId);body={...body,base64:await fileData(blob),mime:blob.type,type:modal.message.type};}if(demo){notify('Demonstração: nenhuma mensagem enviada.');setModal(null);return;}if(await act('send','POST',body,'Mensagem encaminhada.'))setModal(null);}}><Field label="Encaminhar para"><select name="contactId" required><option value="">Selecione um contato</option>{data.contacts.filter(c=>c.id!==selected).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field><p className="form-help">O conteúdo será enviado como uma nova mensagem.</p><button className="btn primary" disabled={busy}>Encaminhar <Send size={16}/></button></form>}
 {['disconnect','deleteMessage','deleteAutomation','cancelMeeting'].includes(modal.type)&&<div className="modal-form"><p>{modal.type==='disconnect'?'Desconectar este WhatsApp do STARSIS? O histórico das conversas será mantido.':modal.type==='deleteMessage'?'Apagar esta mensagem para todos? A remoção depende da permissão e do prazo do WhatsApp.':modal.type==='cancelMeeting'?'Cancelar esta reunião? O registro continuará no histórico.':'Excluir esta automação? Novos follow-ups desta regra deixarão de ser enviados.'}</p><div className="dialog-actions"><button className="btn secondary" onClick={()=>setModal(null)}>Voltar</button><button className="btn danger-btn" disabled={busy} onClick={async()=>{const ok=modal.type==='disconnect'?await act(`numbers/${modal.item.id}/disconnect`):modal.type==='deleteMessage'?await act(`messages/${modal.message.id}`,'DELETE'):modal.type==='cancelMeeting'?await act(`meetings/${modal.item.id}`,'PATCH',{status:'cancelada'}):await act(`automations/${modal.item.id}`,'DELETE');if(ok){if(modal.type==='deleteMessage')loadMessages();setModal(null);}}}>Confirmar</button></div></div>}
